import ballerina/http;

public type Severity "normal"|"medium"|"high"|"critical";

public type SensorEvent readonly & record {|
    string eventId;
    string deviceId;
    string eventType;
    float value;
    string unit;
    int timestamp;
|};

public type RoutingDecision readonly & record {|
    Severity severity;
    string routedTo;
    string reason;
|};

public type NotificationRequest readonly & record {|
    string eventId;
    string deviceId;
    Severity severity;
    string message;
|};

public type NotificationReceipt readonly & record {|
    string notificationId;
    string status;
    int attempt;
|};

public type AcceptedBody readonly & record {|
    string eventId;
    string status;
    Severity severity;
    string routedTo;
    string correlationId;
|};

public type ErrorBody readonly & record {|
    string code;
    string message;
    string correlationId;
|};

public type AcceptedResponse record {|
    *http:Accepted;
    AcceptedBody body;
|};

public type ConflictResponse record {|
    *http:Conflict;
    ErrorBody body;
|};

public type BadRequestResponse record {|
    *http:BadRequest;
    ErrorBody body;
|};

public type ServiceUnavailableResponse record {|
    *http:ServiceUnavailable;
    ErrorBody body;
|};

public type NotifierAcceptedResponse record {|
    *http:Accepted;
    NotificationReceipt body;
|};

public type NotifierErrorResponse record {|
    *http:InternalServerError;
    ErrorBody body;
|};

public type AttemptCount readonly & record {|
    string eventId;
    int attempts;
|};

isolated map<boolean> processedEvents = {};
isolated map<int> notifierAttempts = {};

public isolated function isProcessed(string eventId) returns boolean {
    lock {
        return processedEvents.hasKey(eventId);
    }
}

public isolated function markProcessed(string eventId) {
    lock {
        processedEvents[eventId] = true;
    }
}

public isolated function nextNotifierAttempt(string eventId) returns int {
    lock {
        int nextAttempt = notifierAttempts[eventId] ?: 0;
        nextAttempt += 1;
        notifierAttempts[eventId] = nextAttempt;
        return nextAttempt;
    }
}

public isolated function getNotifierAttempts(string eventId) returns int {
    lock {
        return notifierAttempts[eventId] ?: 0;
    }
}

public isolated function resetPrototypeState() {
    lock {
        processedEvents.removeAll();
    }
    lock {
        notifierAttempts.removeAll();
    }
}

public isolated function validateAndClassify(SensorEvent event) returns RoutingDecision|error {
    if event.eventId.length() < 4 {
        return error("eventId must contain at least four characters");
    }
    if event.deviceId.length() < 3 {
        return error("deviceId must contain at least three characters");
    }
    if event.timestamp <= 0 {
        return error("timestamp must be a positive Unix timestamp");
    }

    match event.eventType {
        "fall" => {
            if event.unit != "boolean" || (event.value != 0.0 && event.value != 1.0) {
                return error("fall events require unit 'boolean' and value 0.0 or 1.0");
            }
            if event.value == 1.0 {
                return {
                    severity: "critical",
                    routedTo: "caregiver-notifier",
                    reason: "fall detected"
                };
            }
            return {
                severity: "normal",
                routedTo: "event-log",
                reason: "no fall detected"
            };
        }
        "vitals" => {
            if event.unit != "bpm" || event.value < 30.0 || event.value > 240.0 {
                return error("vitals events require unit 'bpm' and a value from 30.0 to 240.0");
            }
            if event.value < 50.0 || event.value > 120.0 {
                return {
                    severity: "high",
                    routedTo: "caregiver-notifier",
                    reason: "heart rate outside the prototype threshold"
                };
            }
            return {
                severity: "normal",
                routedTo: "event-log",
                reason: "heart rate inside the prototype threshold"
            };
        }
        "moisture" => {
            if event.unit != "percent" || event.value < 0.0 || event.value > 100.0 {
                return error("moisture events require unit 'percent' and a value from 0.0 to 100.0");
            }
            if event.value >= 80.0 {
                return {
                    severity: "medium",
                    routedTo: "event-log",
                    reason: "moisture crossed the prototype threshold"
                };
            }
            return {
                severity: "normal",
                routedTo: "event-log",
                reason: "moisture inside the prototype threshold"
            };
        }
        _ => {
            return error("unsupported eventType; use fall, vitals, or moisture");
        }
    }
}

import ballerina/http;

configurable string notifierBaseUrl = "http://localhost:9091";

final http:Client notifierClient = check new (notifierBaseUrl, {
    timeout: 1,
    retryConfig: {
        interval: 0.05,
        count: 2,
        backOffFactor: 2.0,
        maxWaitInterval: 0.2
    },
    circuitBreaker: {
        rollingWindow: {
            timeWindow: 10,
            bucketSize: 2,
            requestVolumeThreshold: 10
        },
        failureThreshold: 0.5,
        resetTime: 2,
        statusCodes: [500, 502, 503]
    }
});

public isolated function notifyCaregiver(SensorEvent event, RoutingDecision decision) returns NotificationReceipt|error {
    NotificationRequest notification = {
        eventId: event.eventId,
        deviceId: event.deviceId,
        severity: decision.severity,
        message: decision.reason
    };
    return notifierClient->/notifier/alerts.post(notification);
}

import ballerina/http;

configurable int notifierPort = 9091;

service /notifier on new http:Listener(notifierPort) {
    resource function post alerts(NotificationRequest notification)
            returns NotifierAcceptedResponse|NotifierErrorResponse {
        int attempt = nextNotifierAttempt(notification.eventId);

        if notification.eventId.startsWith("fail-") {
            return {
                body: {
                    code: "SIMULATED_NOTIFIER_FAILURE",
                    message: "synthetic downstream failure",
                    correlationId: notification.eventId
                }
            };
        }

        return {
            body: {
                notificationId: string `notification-${notification.eventId}`,
                status: "delivered",
                attempt
            }
        };
    }

    resource function get attempts/[string eventId]() returns AttemptCount {
        return {eventId, attempts: getNotifierAttempts(eventId)};
    }
}

import ballerina/http;
import ballerina/log;

configurable int servicePort = 9090;

service /api/v1 on new http:Listener(servicePort) {
    isolated resource function get health() returns record {|string status; string serviceName;|} {
        return {status: "UP", serviceName: "sotercare-alert-router"};
    }

    isolated resource function post events(SensorEvent event)
            returns AcceptedResponse|ConflictResponse|BadRequestResponse|ServiceUnavailableResponse {
        string correlationId = event.eventId;

        if isProcessed(event.eventId) {
            ConflictResponse response = {
                body: {
                    code: "DUPLICATE_EVENT",
                    message: "eventId has already been processed",
                    correlationId
                }
            };
            return response;
        }

        RoutingDecision|error result = validateAndClassify(event);
        if result is error {
            BadRequestResponse response = {
                body: {
                    code: "INVALID_EVENT",
                    message: result.message(),
                    correlationId
                }
            };
            return response;
        }

        if result.routedTo == "caregiver-notifier" {
            NotificationReceipt|error notification = notifyCaregiver(event, result);
            if notification is error {
                log:printError("caregiver notification failed", 'error = notification,
                        eventId = event.eventId, deviceId = event.deviceId);
                ServiceUnavailableResponse response = {
                    body: {
                        code: "NOTIFIER_UNAVAILABLE",
                        message: "event was not marked as processed; retry with the same eventId",
                        correlationId
                    }
                };
                return response;
            }
        }

        markProcessed(event.eventId);
        log:printInfo("sensor event accepted", eventId = event.eventId,
                severity = result.severity, routedTo = result.routedTo);
        return {
            body: {
                eventId: event.eventId,
                status: "accepted",
                severity: result.severity,
                routedTo: result.routedTo,
                correlationId
            }
        };
    }
}
